const { chromium } = require('./browser/node_modules/playwright-core');
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const out = path.join(__dirname, 'runtime/review-20261124');
fs.mkdirSync(out, {recursive:true});
const base='http://127.0.0.1:8000/';
const stamp=Date.now();
const prefix='Review '+stamp;
const report={started:new Date().toISOString(),prefix,checks:[],observations:{},accessibility:[],errors:[],fixtures:{emails:[]}};
let browser;
async function check(name,fn){try{const detail=await fn();report.checks.push({name,passed:true,detail});console.log('PASS '+name);}catch(e){report.checks.push({name,passed:false,error:e.message});console.log('FAIL '+name+': '+e.message);}save();}
function save(){if(report.observations.cookies)report.observations.cookies.forEach(c=>delete c.value);fs.writeFileSync(path.join(out,'results.json'),JSON.stringify(report,null,2));}
async function go(p,url){return p.goto(base+url,{waitUntil:'load'});}
async function submit(p,locator){await Promise.all([p.waitForNavigation(),locator.click()]);}
async function login(p,email,password='Review12345'){await go(p,'login.php');await p.locator('#email').fill(email);await p.locator('#password').fill(password);await submit(p,p.locator('.auth-form [type="submit"]'));assert.match(p.url(),/index.php$/);}
async function token(p,url){await go(p,url);return p.locator('input[name="csrf"]').first().inputValue();}
async function shot(p,name){await p.evaluate(()=>document.fonts.ready);await p.screenshot({path:path.join(out,name+'.png'),fullPage:true});}
async function axe(p,name){await p.addScriptTag({path:require.resolve('./browser/node_modules/axe-core/axe.min.js')});const r=await p.evaluate(async()=>{const r=await axe.run({runOnly:{type:'tag',values:['wcag2a','wcag2aa','wcag21aa','wcag22aa']}});return {violations:r.violations.map(v=>({id:v.id,impact:v.impact,help:v.help,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))})),incomplete:r.incomplete.map(v=>({id:v.id,count:v.nodes.length}))};});report.accessibility.push({name,...r});console.log('AXE '+name+' '+r.violations.length);save();}
